def largestUnbiasedProductGroupIn(supplier_network):
    def helper(available_products, chosen_products):
        if not available_products:
            return chosen_products
        product = available_products.pop()
        # Option 1: Include this product
        if not any(product in supplier_network[chosen] for chosen in chosen_products):
            include = helper(available_products, chosen_products | {product})
        else:
            include = chosen_products
        # Option 2: Exclude this product
        exclude = helper(available_products, chosen_products)
        return max(include, exclude, key=len)
    return helper(set(supplier_network.keys()), set())

