def merge_heaps(heap1, heap2):
    if not heap1:
        return heap2
    if not heap2:
        return heap1

    if heap1.score < heap2.score:
        heap1, heap2 = heap2, heap1

    heap1.right = merge_heaps(heap1.right, heap2)

    if not heap1.left or (heap1.left.null_path_length < heap1.right.null_path_length):
        heap1.left, heap1.right = heap1.right, heap1.left

    heap1.null_path_length = (heap1.right.null_path_length + 1) if heap1.right else 1
    return heap1

