int simplifyScore(int &pointsScored, int &pointsAllowed) {
    if (pointsScored <= 0 || pointsAllowed <= 0) {
        return 0;
    }
    int gcd = std::__gcd(pointsScored, pointsAllowed);
    pointsScored /= gcd;
    pointsAllowed /= gcd;
